    {"id": "K2", "group": "K", "cls": "fetch", "consequence": "N:P:Si ratio, not absolute load, selects the assemblage", "blocker": "Total N, total P and silicon are in the held extract; species-level counts are not held, as for {ref:K1}"},
    {"id": "K3", "group": "K", "cls": "experiment", "consequence": "Macronutrient excess induces micronutrient deficiency in tissue", "blocker": "**Tissue elemental analysis of algae and eelgrass is not in the NOVANA protocols**"},
    {"id": "K4", "group": "K", "cls": "unscoreable", "consequence": "Thiamine deficiency propagates up the food web", "blocker": "**No Danish marine thiamine assay** was found. Swedish work exists"},
    {"id": "K5", "group": "K", "cls": "unscoreable", "consequence": "Vitamin `B12` and cobalt limit the auxotrophs", "blocker": "**No marine `B12` or dissolved cobalt measurement for Danish water** was found"},
    {"id": "K6", "group": "K", "cls": "unscoreable", "consequence": "Iron bioavailability limits production or detoxification", "blocker": "No iron speciation for Danish water was found"},
    {"id": "K7", "group": "K", "cls": "resolution", "consequence": "Carbonate ion depletion impairs calcification", "blocker": "pH and total alkalinity are both in the held water-chemistry extract; the temperature and salinity for each bottle come from the CTD record by station and day, not the same hour"},
    {"id": "K8", "group": "K", "cls": "unscoreable", "consequence": "The window between deficient and toxic is narrow and crossed", "blocker": "No dissolved trace metal in the water column in routine monitoring; metals are measured in mussel tissue"},
    {"id": "K9", "group": "K", "cls": "unscoreable", "consequence": "Selenium status limits or intoxicates", "blocker": "Selenium was not confirmed as a determinand in Danish marine biota; mercury is measured"},
    {"id": "K10", "group": "K", "cls": "testable", "consequence": "Salinity change imposes osmotic cost at the range edge", "blocker": "Salinity by station, date and depth is in the CTD record — {fig:da_sal_rows} rows"},
    {"id": "K11", "group": "K", "cls": "testable", "consequence": "Light at the bed = f(Kd, depth), and the product is rarely formed", "blocker": "**Both halves held**: `lys` {fig:da_lys_rows} rows and bottom depth in `maaledybde`, {fig:da_light_paired} paired. Carries the Kd start-depth artefact, and Secchi censoring at the bed: {fig:da_secchi_shallow_pct}% of paired readings in water shallower than {fig:da_secchi_shallow_to} m reach the bed"},
    {"id": "K12", "group": "K", "cls": "fetch", "consequence": "Structure removal -> habitat loss independent of water quality", "blocker": "Stone extraction records, reef restoration locations and dates: not published as data, to be obtained from the projects"},
    {"id": "K13", "group": "K", "cls": "unscoreable", "consequence": "Particle spectra shift below the filter-feeder window", "blocker": "**No particle size spectrum or larval condition index for Danish water** was found, by a keyword search"},
    {"id": "K14", "group": "K", "cls": "fetch", "consequence": "Functional diversity falls before species richness does", "blocker": "ODA bundfauna, joined to a trait table"},
    {"id": "W1", "group": "W", "cls": "resolution", "consequence": "Recovery fails where propagule supply is cut", "blocker": "Source populations plus particle tracking: no national eelgrass or mussel-bed layer was reachable, no connectivity matrix is deposited, and the held current field does not resolve the straits"},
    {"id": "W2", "group": "W", "cls": "experiment", "consequence": "Unconditioned substrate fails to recruit", "blocker": "**Settlement plates with and without conditioning.** Connects to the sediment-inoculation experiment `X1`"},
    {"id": "W3", "group": "W", "cls": "fetch", "consequence": "Bloom and larval peak drift apart", "blocker": "Plankton counts: NOVANA samples plankton through the growing season at its primary-production stations, and the counts are in VanDa, which refused access; not held"},
    {"id": "W4", "group": "W", "cls": "fetch", "consequence": "Below a density threshold reproduction fails", "blocker": "ODA bundfauna carries densities per grab; the analysis is then a desk exercise"},
    {"id": "W5", "group": "W", "cls": "fetch", "consequence": "Disturbance interval shorter than recovery time", "blocker": "**Trawling effort at monthly or finer.** Every public product found is annual; the timestamped VMS positions are inside ICES"},
    {"id": "W6", "group": "W", "cls": "testable", "consequence": "Rate of change exceeds acclimation rate", "blocker": "The CTD record supports a rate analysis over years; genuinely high-frequency temperature is at tide gauges, not at the bed"},
    {"id": "W8", "group": "W", "cls": "experiment", "consequence": "The founder community determines the endpoint", "blocker": "Composition immediately after disturbance and through recovery at the same place — requires having sampled before"},
