    {"id": "Z3", "group": "Z", "cls": "unscoreable", "consequence": "Photoperiod cue decouples from temperature cue", "blocker": "**No phenological observation series for Danish marine invertebrates** was found"},
    {"id": "Z4", "group": "Z", "cls": "resolution", "consequence": "Rate of temperature change, not level, exceeds tolerance", "blocker": "Bottom temperature at high frequency; the monthly product aliases it, and the raw bed record resolves multi-year rates, not event onset"},
    {"id": "Z5", "group": "Z", "cls": "testable", "consequence": "Energy has a floor — too still is also a failure", "blocker": "Bed shear already computed here from {fig:da_wind_years} years of wind; the floor is testable against the same state variables"},
