    {"id": "R11", "group": "R", "cls": "unscoreable", "consequence": "Marine fungi decompose and nobody counts them", "blocker": "**No marine fungal biomass measurement** was found, and the Danish marine fungal barcode record is an ARMS deployment at Læsø"},
    {"id": "R1", "group": "R", "cls": "fetch", "consequence": "C:N of discharged material decides whether it is a sink", "blocker": "Organic carbon is reported for large industry and N and COD at stream stations; **fat is not a reported pollutant**"},
